    64	            }
    65	            if (shouldShowOnlyViolations) {
    66	                return violation.type === CONST.VIOLATION_TYPES.VIOLATION;
    67	            }
    68	            return true;
    69	        });
    70	
    71	        const violationGroups = new Map<ViolationField, TransactionViolation[]>();
    72	        for (const violation of filteredViolations) {
    73	            const field = violationFields[violation.name];
    74	            const existingViolations = violationGroups.get(field) ?? [];
    75	            violationGroups.set(field, [...existingViolations, violation]);
    76	        }
    77	        return violationGroups ?? new Map();
    78	    }, [violations, shouldShowOnlyViolations]);
