    85	            // tagListIndex can be 0 so we compare with undefined
    86	            if (currentViolations[0]?.name === CONST.VIOLATIONS.SOME_TAG_LEVELS_REQUIRED && data?.tagListIndex !== undefined && Array.isArray(currentViolations[0]?.data?.errorIndexes)) {
    87	                return currentViolations
    88	                    .filter((violation) => violation.data?.errorIndexes?.includes(data?.tagListIndex ?? -1))
    89	                    .map((violation) => ({
    90	                        ...violation,
    91	                        data: {
    92	                            ...violation.data,
    93	                            tagName: data?.tagListName,
    94	                        },
    95	                    }));
    96	            }
    97	
    98	            // missingTag has special logic for policies with dependent tags, because only one violation is returned for all tags
    99	            // when no tags are present, so the tag name isn't set in the violation data. That's why we add it here
   100	            if (policyHasDependentTags && currentViolations[0]?.name === CONST.VIOLATIONS.MISSING_TAG && data?.tagListName) {
   101	                return [
   102	                    {
   103	                        ...currentViolations[0],
   104	                        data: {
   105	                            ...currentViolations[0].data,
   106	                            tagName: data?.tagListName,
   107	                        },
   108	                    },
   109	                ];
   110	            }
   111	
   112	            // tagOutOfPolicy has special logic because we have to account for multi-level tags and use tagName to find the right tag to put the violation on
