   114	                return currentViolations.filter((violation) => violation.data?.tagName === data?.tagListName);
   115	            }
   116	
   117	            // allTagLevelsRequired has special logic because it is returned when one but not all the tags are set,
   118	            // so we need to return the violation for the tag fields without a tag set
   119	            if (currentViolations[0]?.name === CONST.VIOLATIONS.ALL_TAG_LEVELS_REQUIRED && tagValue) {
   120	                return currentViolations.filter((violation) => violation.data?.tagName === data?.tagListName);
   121	            }
   122	
   123	            return currentViolations;
   124	        },
   125	        [violationsByField],
   126	    );
